static inline const uint8_t *cn_find_glyph(const char *utf8) {
    for (unsigned i = 0; i < CN_GLYPH_COUNT; ++i) {
        if (strcmp(utf8, CN_GLYPHS[i].ch) == 0) return CN_GLYPHS[i].data;
    }
    return NULL;
}

